import json
def spec(mark, rows, enc, **kw):
    s = {"width": 300, "height": 200, "data": {"values": rows}, "mark": mark, "encoding": enc}
    s.update(kw); return s
Q = lambda f, **k: dict({"field": f, "type": "quantitative"}, **k)
N = lambda f, **k: dict({"field": f, "type": "nominal"}, **k)
O = lambda f, **k: dict({"field": f, "type": "ordinal"}, **k)
T = lambda f, **k: dict({"field": f, "type": "temporal"}, **k)
abc = [{"k": "a", "v": 1}, {"k": "b", "v": 2}, {"k": "c", "v": 3}]
two = [{"c": c, "g": g, "v": v} for c, g, v in [("x","a",3),("x","b",1),("y","a",2),("y","b",6),("z","a",4),("z","b",4)]]
S = {}
S["g01_line_quant_x"] = spec("line", [{"x":50,"y":1},{"x":60,"y":2}], {"x":Q("x"),"y":Q("y")})
S["g01b_area_quant_x"] = spec("area", [{"x":50,"y":1},{"x":60,"y":2}], {"x":Q("x"),"y":Q("y")})
S["g02_arc_abc"] = spec("arc", abc, {"theta":Q("v"),"color":N("k")})
S["g03_hbar_stack"] = spec("bar", two, {"y":N("c"),"x":Q("v"),"color":N("g")})
S["g03b_vbar_stack"] = spec("bar", two, {"x":N("c"),"y":Q("v"),"color":N("g")})
S["g04a_arc_color_desc"] = spec("arc", abc, {"theta":Q("v"),"color":N("k",sort="descending")})
S["g04b_bar_color_list"] = spec("bar", two, {"x":N("c"),"y":Q("v"),"color":N("g",sort=["b","a"])})
S["g04c_arc_color_list"] = spec("arc", abc, {"theta":Q("v"),"color":N("k",sort=["c","a","b"])})
S["g06_normalize_neg"] = spec("bar", [{"c":"x","g":"a","v":3},{"c":"x","g":"b","v":-1},{"c":"y","g":"a","v":2},{"c":"y","g":"b","v":2}], {"x":N("c"),"y":Q("v",stack="normalize"),"color":N("g")})
S["g07_count_ordinal"] = spec("bar", [{"k":"a"},{"k":"a"},{"k":"b"}], {"x":N("k"),"y":{"aggregate":"count","type":"ordinal"}})
S["g07b_count_temporal"] = spec("bar", [{"k":"a"},{"k":"a"},{"k":"b"}], {"x":N("k"),"y":{"aggregate":"count","type":"temporal"}})
mean_rows = [{"k":"a","g":"p","v":1},{"k":"a","g":"q","v":9},{"k":"b","g":"p","v":5},{"k":"b","g":"q","v":5},{"k":"c","g":"p","v":30},{"k":"c","g":"q","v":2}]
S["g08a_sort_mean"] = spec("bar", mean_rows, {"x":N("k",sort="-y"),"y":Q("v",aggregate="mean"),"color":N("g")})
S["g08b_sort_max"] = spec("bar", mean_rows, {"x":N("k",sort="-y"),"y":Q("v",aggregate="max")})
S["g08c_sort_x_raw"] = spec("point", [{"k":"a","v":5},{"k":"a","v":5},{"k":"b","v":8},{"k":"c","v":1},{"k":"c","v":1},{"k":"c","v":1}], {"y":N("k",sort="x"),"x":Q("v")})
S["g09a_domain_nice"] = spec("point", [{"x":2,"y":1},{"x":7,"y":2}], {"x":Q("x",scale={"domain":[1.3,8.7],"nice":True}),"y":Q("y")})
S["g09b_domain_zero"] = spec("point", [{"x":2,"y":1},{"x":7,"y":2}], {"x":Q("x",scale={"domain":[1.3,8.7],"zero":True}),"y":Q("y")})
S["g09c_temporal_nice"] = spec("point", [{"d":"2024-01-03","y":1},{"d":"2024-01-20","y":2}], {"x":T("d",scale={"nice":True}),"y":Q("y")})
S["g10_opacity_bar_off"] = spec("bar", two, {"x":N("c"),"y":Q("v",stack=None),"color":N("g")})
S["g10b_opacity_area_off"] = spec("area", [{"x":1,"g":"a","v":3},{"x":2,"g":"a","v":4},{"x":1,"g":"b","v":2},{"x":2,"g":"b","v":5}], {"x":Q("x"),"y":Q("v",stack=None),"color":N("g")})
S["g10c_opacity_area_stack"] = spec("area", [{"x":1,"g":"a","v":3},{"x":2,"g":"a","v":4},{"x":1,"g":"b","v":2},{"x":2,"g":"b","v":5}], {"x":Q("x"),"y":Q("v"),"color":N("g")})
S["g10d_opacity_point"] = spec("point", [{"x":1,"y":2},{"x":2,"y":3}], {"x":Q("x"),"y":Q("y")})
S["g10e_opacity_bar"] = spec("bar", abc, {"x":N("k"),"y":Q("v")})
S["g11_normalize_nocolor"] = spec("bar", abc, {"x":N("k"),"y":Q("v",stack="normalize")})
S["g12_null_cat_sort"] = spec("bar", [{"k":None,"v":1},{"k":"a","v":2},{"v":3},{"k":"b","v":4}], {"x":N("k"),"y":Q("v")})
S["g12b_sum_allnull"] = spec("bar", [{"k":"a","v":None},{"k":"b","v":2},{"k":"b","v":3}], {"x":N("k"),"y":Q("v",aggregate="sum")})
S["g12c_sort_list_unlisted"] = spec("bar", [{"k":"q","v":1},{"k":"a","v":2},{"k":"z","v":3},{"k":"b","v":4}], {"x":N("k",sort=["b"]),"y":Q("v")})
S["g13_neg_arc"] = spec("arc", [{"k":"a","v":3},{"k":"b","v":-1},{"k":"c","v":2}], {"theta":Q("v"),"color":N("k")})
S["g14_line_stack_color"] = spec("line", [{"x":1,"g":"a","v":3},{"x":2,"g":"a","v":4},{"x":1,"g":"b","v":2},{"x":2,"g":"b","v":5}], {"x":Q("x"),"y":Q("v",stack="zero"),"color":N("g")})
S["g15_ordinal_y_count_hbar"] = spec("bar", abc, {"y":N("k"),"x":Q("v")})
S["g16_line_quant_zero_false"] = spec("line", [{"x":50,"y":1},{"x":60,"y":2}], {"x":Q("x"),"y":Q("y")})
json.dump(S, open("specs.json","w"), indent=1)
S["g08d_sort_op_raw"] = spec("point", [{"k":"a","v":1},{"k":"a","v":9},{"k":"b","v":4},{"k":"c","v":6},{"k":"c","v":6}], {"y":N("k",sort="x"),"x":Q("v")})
S["g08e_sort_op_mean_color"] = spec("bar", [{"k":"a","g":"p","v":1},{"k":"a","g":"q","v":9},{"k":"b","g":"p","v":5},{"k":"b","g":"q","v":5},{"k":"c","g":"p","v":6},{"k":"c","g":"q","v":6}], {"x":N("k",sort="-y"),"y":Q("v",aggregate="mean"),"color":N("g")})
S["g08f_sort_op_sum_raw_y"] = spec("bar", [{"k":"a","v":1},{"k":"a","v":9},{"k":"b","v":4},{"k":"c","v":6},{"k":"c","v":6}], {"x":N("k",sort="-y"),"y":Q("v")})
S["g17_dup_values_bar_nocolor"] = spec("bar", [{"k":"a","v":1},{"k":"a","v":2}], {"x":N("k"),"y":Q("v")})
json.dump(S, open("specs.json","w"), indent=1)
S["g08g_sort_sum_vs_mean"] = spec("bar", [{"k":"a","v":1},{"k":"a","v":1},{"k":"a","v":1},{"k":"a","v":1},{"k":"b","v":3}], {"x":N("k",sort="-y"),"y":Q("v")})
S["g08h_max_color_sort"] = spec("bar", [{"k":"a","g":"p","v":1},{"k":"a","g":"q","v":9},{"k":"b","g":"p","v":4},{"k":"b","g":"q","v":4},{"k":"c","g":"p","v":2},{"k":"c","g":"q","v":6}], {"x":N("k",sort="-y"),"y":Q("v",aggregate="max"),"color":N("g")})
S["g08i_hbar_sort_x"] = spec("bar", [{"k":"a","v":1},{"k":"a","v":1},{"k":"a","v":1},{"k":"a","v":1},{"k":"b","v":3}], {"y":N("k",sort="x"),"x":Q("v")})
json.dump(S, open("specs.json","w"), indent=1)
S["g20_number_reading"] = spec("bar", [{"k":"a","v":True},{"k":"b","v":[5]},{"k":"c","v":"0x10"},{"k":"d","v":""},{"k":"e","v":" 7 "},{"k":"f","v":None},{"k":"g","v":"abc"},{"k":"h","v":[1,2]},{"k":"i","v":"1e2"},{"k":"j","v":False}], {"x":N("k"),"y":Q("v")})
json.dump(S, open("specs.json","w"), indent=1)
